/** Same upload/preview/one-confirmation owner workflow, with separate MCQ membership. */
final class CAFCC_MCQ_Admin {
    public static function selection($f){
        global $wpdb;$w='1=1';$a=array();$scope=$f['scope']??'current';if(!in_array($scope,array('current','package','all'),true))return CAFCC_Repository::error('Choose the current MCQ dataset, a package, or all.');$pid=$scope==='current'?(int)get_option('cafcc_current_mcq_package',0):(int)($f['package_id']??0);if($scope!=='all'){$w.=' AND EXISTS(SELECT 1 FROM '.CAFCC_MCQ::table('members').' membership WHERE membership.mcq_id=m.id AND membership.package_id=%d)';$a[]=$pid;}
        foreach(array('subject'=>'subject_code','publication'=>'publication_status') as $k=>$col)if(!empty($f[$k])){if(!is_string($f[$k])||strlen($f[$k])>32)return CAFCC_Repository::error('Invalid MCQ library filter.');$w.=" AND m.$col=%s";$a[]=$f[$k];}
        if(!empty($f['search'])){$term=$f['search'];if(!is_string($term)||strlen($term)>190)return CAFCC_Repository::error('Use a short MCQ search.');$w.=' AND (m.stable_id LIKE %s OR m.search_text LIKE %s)';$a[]='%'.$wpdb->esc_like($term).'%';$a[]='%'.$wpdb->esc_like(CAFCC_Search_Tags::normalise($term)).'%';}
        if(isset($f['ids'])){if(!is_array($f['ids'])||!array_is_list($f['ids'])||count($f['ids'])>1000||!$f['ids'])return CAFCC_Repository::error('Select MCQs or choose Select All Filtered.');$ids=array();foreach($f['ids'] as $id){if(!is_int($id)||$id<1)return CAFCC_Repository::error('Invalid selected MCQ.');$ids[]=$id;}$w.=' AND m.id IN ('.implode(',',array_fill(0,count($ids),'%d')).')';array_push($a,...$ids);}return array($w,$a);
    }
    public static function library($f){global $wpdb;$sel=self::selection($f);if(is_wp_error($sel))return $sel;[$w,$a]=$sel;$page=max(1,(int)($f['page']??1));$t=CAFCC_MCQ::table('questions');$count=$wpdb->get_var($a?$wpdb->prepare("SELECT COUNT(*) FROM $t m WHERE $w",$a):"SELECT COUNT(*) FROM $t m WHERE $w");$sql="SELECT m.id,m.stable_id,m.revision,m.subject_code,m.source_type,m.exam_attempt,m.mtp_series,m.question_number,m.publication_status FROM $t m WHERE $w ORDER BY m.id LIMIT 30 OFFSET ".(($page-1)*30);$rows=$wpdb->get_results($a?$wpdb->prepare($sql,$a):$sql,ARRAY_A);foreach($rows as &$r){$r['subquestion_number']='';$r['tags']=CAFCC_MCQ::tags($r['id']);$r['owner_publication']='provisional';$r['archived']='0';}return array('items'=>$rows,'total'=>(int)$count,'page'=>$page,'record_kind'=>'mcq');}
    public static function plan($f,$action){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!in_array($action,array('publish','unpublish','drafts'),true))return CAFCC_Repository::error('Choose Publish, Unpublish or Save Drafts.');$sel=self::selection($f);if(is_wp_error($sel))return $sel;global $wpdb;[$w,$a]=$sel;$sql='SELECT m.id,m.revision FROM '.CAFCC_MCQ::table('questions')." m WHERE $w ORDER BY m.id LIMIT 10001";$rows=$wpdb->get_results($a?$wpdb->prepare($sql,$a):$sql,ARRAY_A);if(!$rows||count($rows)>10000)return CAFCC_Repository::error('Select between one and 10,000 MCQs.');$key=wp_generate_uuid4();if(false===$wpdb->insert(CAFCC_MCQ::table('jobs'),array('job_key'=>$key,'owner_id'=>get_current_user_id(),'action_name'=>$action,'phase'=>'planning','payload'=>wp_json_encode(array('records'=>$rows,'selection'=>$f)),'report'=>wp_json_encode(array('selected'=>count($rows),'eligible'=>0,'warnings'=>0,'blocked'=>array(),'changed'=>0,'provisionally_published'=>0,'answer_pending'=>0)),'created_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Cannot retain MCQ preview.',500);return self::job($key);
    }
    public static function job($key,$lock=false){global $wpdb;if(!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/D',$key))return CAFCC_Repository::error('Invalid action key.');$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.CAFCC_MCQ::table('jobs').' WHERE job_key=%s AND owner_id=%d'.($lock?' FOR UPDATE':''),$key,get_current_user_id()),ARRAY_A);if(!$r)return CAFCC_Repository::error('Private MCQ action not found.',404);$r['data']=json_decode($r['payload'],true);$r['report']=json_decode($r['report'],true);$r['record_kind']='mcq';unset($r['payload']);return $r;}
    public static function step($key,$v){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;return CAFCC_Academic::transaction(function()use($key,$v){global $wpdb;$j=self::job($key,true);if(is_wp_error($j))return $j;$cursor=(int)$j['cursor_position'];if(!is_int($v['cursor']??null))return CAFCC_Repository::error('Supply the current integer cursor.');if($j['phase']==='completed'||$v['cursor']<$cursor)return $j;if($v['cursor']!==$cursor)return CAFCC_Repository::error('Action cursor changed.',409);$planning=$j['phase']==='planning';if(!$planning&&(true!==($v['confirmed']??false)||($j['action_name']==='publish'&&true!==($v['accept_provisional']??false))))return CAFCC_Repository::error('Confirm this exact batch once; classification remains provisional.',409);if(!$planning)$j['confirmed_at']=$j['confirmed_at']?:current_time('mysql',true);$rows=&$j['data']['records'];$until=min(count($rows),$cursor+10);
            for(;$cursor<$until;$cursor++){$row=&$rows[$cursor];$r=CAFCC_MCQ::get($row['id'],true);$msg='';if(!$r||(int)$r['revision']!==(int)$row['revision'])$msg='Changed since preview. Retained without overwriting.';elseif(!$planning&&!empty($row['blocked']))$msg='Blocked in this preview. Correct and preview again.';else{$q=$j['action_name']==='publish'?CAFCC_MCQ::quality($r):array('blocks'=>array(),'warnings'=>array());if($q['blocks'])$msg=implode(' ',$q['blocks']);elseif($planning){$j['report']['eligible']++;if($q['warnings'])$j['report']['warnings']++;}elseif($j['action_name']!=='drafts'){$before=$r;$fields=array('publication_status'=>$j['action_name']==='publish'?'published':'draft','modified_at'=>current_time('mysql',true));if($j['action_name']==='publish'){$fields['rights_grant_id']=(int)$q['grant']['id'];$fields['rights_grant_revision']=(int)$q['grant']['revision'];$fields['permission_required']=1;$fields['publication_fingerprint']=CAFCC_MCQ::fingerprint($r);}$ok=$wpdb->update(CAFCC_MCQ::table('questions'),$fields,array('id'=>$r['id']));if(false===$ok||!CAFCC_Bank_DB::audit_master('mcq_owner_'.$j['action_name'],$r['id'],$before,array('record'=>CAFCC_MCQ::get($r['id']),'owner_batch_confirmation'=>$j['confirmed_at'],'academic_verification'=>'not_independently_verified')))return CAFCC_Repository::error('MCQ publication checkpoint failed.',500);$j['report']['changed']++;if($j['action_name']==='publish')$j['report']['provisionally_published']++;}}
                if($msg){$row['blocked']=true;$j['report']['blocked'][(string)$row['id']]=array('id'=>$row['id'],'stable_id'=>$r['stable_id']??'','message'=>$msg);}
            }unset($row);if($cursor===count($rows)){$j['phase']=$planning?'ready':'completed';if($planning)$cursor=0;}$j['cursor_position']=$cursor;if(false===$wpdb->update(CAFCC_MCQ::table('jobs'),array('phase'=>$j['phase'],'cursor_position'=>$cursor,'confirmed_at'=>$j['confirmed_at'],'payload'=>wp_json_encode($j['data']),'report'=>wp_json_encode($j['report'])),array('id'=>$j['id'])))return CAFCC_Repository::error('Cannot retain MCQ action progress.',500);return self::job($key);
        });
    }
    public static function correct($id,$v){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($v)||array_diff(array_keys($v),array('expected_revision','data','action','accept_provisional')))return CAFCC_Repository::error('Invalid MCQ correction.');return CAFCC_Academic::transaction(function()use($id,$v){global $wpdb;$r=CAFCC_MCQ::get($id,true);if(!$r||(int)($v['expected_revision']??0)!==(int)$r['revision'])return CAFCC_Repository::error('Stale MCQ correction. Reload the current revision.',409);$d=CAFCC_MCQ::clean($v['data']??null);if(is_wp_error($d))return $d;if($d['stable_id']!==$r['stable_id']||CAFCC_MCQ::identity($d)!==$r['identity_hash']||$d['source_occurrence_id']!==$r['occurrence_key'])return CAFCC_Repository::error('Source occurrence identity cannot be remapped by a content edit.');if(($d['scenario']??null)!==($r['data']['scenario']??null))return CAFCC_Repository::error('Shared facts require a source-wide correction; dependent records must be reviewed together.');$fields=array('revision'=>(int)$r['revision']+1,'publication_status'=>'draft','publication_fingerprint'=>'','question_html'=>$d['question_html'],'options_json'=>wp_json_encode($d['options']),'correct_json'=>wp_json_encode($d['correct_options']),'key_policy'=>$d['key_policy'],'key_verified'=>$d['key_verified']?1:0,'payload'=>wp_json_encode($d),'search_text'=>CAFCC_Search_Tags::normalise(wp_strip_all_tags($d['question_html'].' '.($d['scenario']['html']??''))),'modified_at'=>current_time('mysql',true));if(false===$wpdb->update(CAFCC_MCQ::table('questions'),$fields,array('id'=>$id)))return CAFCC_Repository::error('Cannot retain MCQ correction.',500);$saved=CAFCC_MCQ::get($id);$tagged=CAFCC_MCQ::save_tags($saved);if(is_wp_error($tagged)||!CAFCC_Bank_DB::audit_master('mcq_corrected',$id,$r,$saved))return CAFCC_Repository::error('Cannot retain MCQ revision history.',500);return $saved;});
    }
    public static function preview($id){global $wpdb;$items=$wpdb->get_results($wpdb->prepare('SELECT payload FROM '.CAFCC_Package::items_table()." WHERE package_id=%d AND kind='mcqs' ORDER BY ordinal",$id),ARRAY_A);$out=array('record_kind'=>'mcq','count'=>0,'question_bodies'=>0,'answer_candidates'=>0,'sources'=>0,'samples'=>array(),'existing_rights_active'=>false);foreach($items as $item)foreach(json_decode($item['payload'],true)['records'] as $d){$out['count']++;$out['question_bodies']+=!empty($d['question_html']);$out['answer_candidates']+=!empty($d['correct_options']);$out['sources']+=!empty($d['official_url']);if(count($out['samples'])<4)$out['samples'][]=array('label'=>strtoupper($d['source_type']).' '.$d['mtp_series'].' Q'.$d['reference'],'question'=>CAFCC_Practice::html(($d['scenario']['html']??'').$d['question_html'].implode('',array_column($d['options'],'html'))),'answer'=>'Printed key: '.implode(', ',$d['correct_options']).' · '.esc_html(implode('; ',$d['exceptions'])));}$out['existing_rights_active']=(bool)$wpdb->get_var('SELECT id FROM '.CAFCC_Rights::table()." WHERE state='active' LIMIT 1");return $out;}
    public static function init(){add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};$routes=array('/admin/mcq/library'=>array('GET',function($r){return self::library($r->get_params());}),'/admin/mcq/plan'=>array('POST',function($r){$d=CAFCC_Studio::body($r);return is_wp_error($d)?$d:self::plan($d['filter']??array(),$d['action']??'');}),'/admin/mcq/detail/(?P<id>[1-9][0-9]*)'=>array('GET',function($r){$d=CAFCC_MCQ::get((int)$r['id']);if(!$d)return CAFCC_Repository::error('MCQ not found.',404);$d['checklist']=CAFCC_MCQ::quality($d);return $d;}),'/admin/mcq/correct/(?P<id>[1-9][0-9]*)'=>array('POST',function($r){$d=CAFCC_Studio::body($r,1500000);return is_wp_error($d)?$d:self::correct((int)$r['id'],$d);}),'/admin/mcq/packages'=>array('GET',function(){global $wpdb;return array('current'=>(int)get_option('cafcc_current_mcq_package',0),'items'=>$wpdb->get_results('SELECT p.id,p.package_key,COUNT(m.mcq_id) AS members FROM '.CAFCC_Package::table().' p JOIN '.CAFCC_MCQ::table('members').' m ON m.package_id=p.id GROUP BY p.id,p.package_key ORDER BY p.id DESC',ARRAY_A));}));foreach($routes as $path=>$route)register_rest_route('cafcc/v9',$path,array('methods'=>$route[0],'permission_callback'=>$p,'callback'=>$route[1]));register_rest_route('cafcc/v9','/admin/mcq/jobs/(?P<key>[a-f0-9-]{36})',array(array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){return self::job($r['key']);}),array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:self::step($r['key'],$v);})));});}
}
